PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS "Usuario" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "nome" TEXT NOT NULL, "email" TEXT NOT NULL, "senhaHash" TEXT NOT NULL, "role" TEXT NOT NULL DEFAULT 'CLIENTE', "consentimentoLgpd" BOOLEAN NOT NULL DEFAULT false, "consentimentoEm" DATETIME, "criadoEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "atualizadoEm" DATETIME NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "Usuario_email_key" ON "Usuario"("email");
CREATE TABLE IF NOT EXISTS "Unidade" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "nome" TEXT NOT NULL, "cidade" TEXT NOT NULL, "uf" TEXT NOT NULL, "ativa" BOOLEAN NOT NULL DEFAULT true, "criadoEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "Produto" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "nome" TEXT NOT NULL, "descricao" TEXT, "preco" DECIMAL NOT NULL, "ativo" BOOLEAN NOT NULL DEFAULT true, "criadoEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "Estoque" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "unidadeId" INTEGER NOT NULL, "produtoId" INTEGER NOT NULL, "quantidade" INTEGER NOT NULL DEFAULT 0, "atualizadoEm" DATETIME NOT NULL, CONSTRAINT "Estoque_unidadeId_fkey" FOREIGN KEY ("unidadeId") REFERENCES "Unidade"("id"), CONSTRAINT "Estoque_produtoId_fkey" FOREIGN KEY ("produtoId") REFERENCES "Produto"("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "Estoque_unidadeId_produtoId_key" ON "Estoque"("unidadeId", "produtoId");
CREATE TABLE IF NOT EXISTS "MovimentoEstoque" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "estoqueId" INTEGER NOT NULL, "tipo" TEXT NOT NULL, "quantidade" INTEGER NOT NULL, "motivo" TEXT NOT NULL, "criadoEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MovimentoEstoque_estoqueId_fkey" FOREIGN KEY ("estoqueId") REFERENCES "Estoque"("id"));
CREATE TABLE IF NOT EXISTS "Pedido" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "clienteId" INTEGER NOT NULL, "unidadeId" INTEGER NOT NULL, "canalPedido" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'AGUARDANDO_PAGAMENTO', "total" DECIMAL NOT NULL, "criadoEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "atualizadoEm" DATETIME NOT NULL, CONSTRAINT "Pedido_clienteId_fkey" FOREIGN KEY ("clienteId") REFERENCES "Usuario"("id"), CONSTRAINT "Pedido_unidadeId_fkey" FOREIGN KEY ("unidadeId") REFERENCES "Unidade"("id"));
CREATE TABLE IF NOT EXISTS "ItemPedido" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "pedidoId" INTEGER NOT NULL, "produtoId" INTEGER NOT NULL, "quantidade" INTEGER NOT NULL, "precoUnitario" DECIMAL NOT NULL, "subtotal" DECIMAL NOT NULL, CONSTRAINT "ItemPedido_pedidoId_fkey" FOREIGN KEY ("pedidoId") REFERENCES "Pedido"("id") ON DELETE CASCADE, CONSTRAINT "ItemPedido_produtoId_fkey" FOREIGN KEY ("produtoId") REFERENCES "Produto"("id"));
CREATE TABLE IF NOT EXISTS "Pagamento" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "pedidoId" INTEGER NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDENTE', "transacaoId" TEXT NOT NULL, "motivoRecusa" TEXT, "payload" TEXT NOT NULL, "processadoEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Pagamento_pedidoId_fkey" FOREIGN KEY ("pedidoId") REFERENCES "Pedido"("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "Pagamento_pedidoId_key" ON "Pagamento"("pedidoId");
CREATE UNIQUE INDEX IF NOT EXISTS "Pagamento_transacaoId_key" ON "Pagamento"("transacaoId");
CREATE TABLE IF NOT EXISTS "Auditoria" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "usuarioId" INTEGER, "acao" TEXT NOT NULL, "recurso" TEXT NOT NULL, "recursoId" TEXT, "detalhes" TEXT, "criadoEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Auditoria_usuarioId_fkey" FOREIGN KEY ("usuarioId") REFERENCES "Usuario"("id"));
